"""Exact, self-contained audit of Theorem W_k on the surviving optimal-network corpus.

No floating point and no imports from another agent's theorem implementation.
The forced depth d is the least integer satisfying
    (n-1)/2^d <= 1-2^-k,
checked after clearing denominators.  Default corpus:
commons/data/agent-0194_optimal_network_corpus_20260805T1655Z.json
"""
import argparse, json
from fractions import Fraction

DEFAULT = "commons/data/agent-0194_optimal_network_corpus_20260805T1655Z.json"
# Exact, locally/provenance-supported cells needed for corpus n=4..8.
S = {3: 3, 4: 5, 5: 9, 6: 12, 7: 16, 8: 19}

def forced_d(n, k):
    """Least d with (n-1)2^-d <= 1-2^-k, integer arithmetic only."""
    if n < 2 or k < 1:
        raise ValueError("need n>=2 and k>=1")
    d = 0
    # (n-1)*2^k <= (2^k-1)*2^d
    while (n - 1) * (1 << k) > ((1 << k) - 1) * (1 << d):
        d += 1
    return d

def sorts(net, n):
    for x in range(1 << n):
        a = [(x >> i) & 1 for i in range(n)]
        for i, j in net:
            if a[i] > a[j]:
                a[i], a[j] = a[j], a[i]
        if a != sorted(a):
            return False
    return True

def min_trajectory_lengths(net, n):
    """Comparator counts on trajectories of -infinity sentinels from each source."""
    ans = []
    for source in range(n):
        pos = source
        ell = 0
        for i, j in net:
            if pos == i:
                ell += 1                 # minimum stays on low output i
            elif pos == j:
                ell += 1
                pos = i                  # minimum moves to low output i
        ans.append(ell)
    return ans

def degree(net, c):
    return sum(c == i or c == j for i, j in net)

def audit(path=DEFAULT):
    raw = json.load(open(path))
    checked = sort_fail = kraft_fail = d0_fail = wk_fail = 0
    by_n = {}
    for ns, rows in sorted(raw["networks"].items(), key=lambda z: int(z[0])):
        n = int(ns)
        for row in rows:
            net = [tuple(x) for x in row["network"]]
            checked += 1
            by_n[n] = by_n.get(n, 0) + 1
            if not sorts(net, n): sort_fail += 1
            ell = min_trajectory_lengths(net, n)
            k = degree(net, 0)
            if ell[0] != k: d0_fail += 1
            if sum((Fraction(1, 1 << x) for x in ell), Fraction()) > 1:
                kraft_fail += 1
            if n - 1 in S and len(net) < S[n-1] + forced_d(n, k):
                wk_fail += 1
    return dict(checked=checked, by_n=by_n, sort_fail=sort_fail,
                kraft_fail=kraft_fail, d0_fail=d0_fail, wk_fail=wk_fail)

def selftest():
    assert forced_d(8, 1) == 4
    assert forced_d(8, 2) == 4
    assert forced_d(8, 3) == 3
    assert forced_d(10, 2) == 4
    # Boundary equality: 7/16 = 1-1/2^? No: k=2 gives 3/4, and 7/16 fits.
    assert Fraction(7, 1 << forced_d(8, 2)) <= 1 - Fraction(1, 4)
    # D0 on a network where channel 0 occurs multiple times.
    net = [(0,1),(1,2),(0,2),(0,1)]
    assert min_trajectory_lengths(net, 3)[0] == degree(net, 0) == 3
    r = audit()
    assert r["checked"] == 172, r
    assert r["by_n"] == {4:12, 5:40, 6:40, 7:40, 8:40}, r
    assert not any(r[x] for x in ("sort_fail","kraft_fail","d0_fail","wk_fail")), r
    print("PASS exact W_k audit")
    print(json.dumps(r, sort_keys=True))

if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--corpus", default=DEFAULT)
    ap.add_argument("--selftest", action="store_true")
    a = ap.parse_args()
    if a.selftest:
        selftest()
    else:
        print(json.dumps(audit(a.corpus), indent=2, sort_keys=True))
